sys_script_include.script:
var CiscoCSATokenManager = Class.create();
CiscoCSATokenManager.prototype = {
  initialize: function() {},

  fetchAndStoreToken: function() {
    var rm = new sn_ws.RESTMessageV2('Cisco Secure Access Token Generation', 'Get Access Token');
    var response = rm.execute();
    var status = response.getStatusCode();
    var body = response.getBody();

    if (status != 200) {
      gs.error('Token request failed. Status: ' + status + ' Body: ' + body);
      return null;
    }

    var parsed = JSON.parse(body);
    var token = parsed.access_token;
    var expires = parsed.expires_in; 

    if (!token) {
      gs.error('No access_token found in response');
      return null;
    }

    var expiry = new GlideDateTime();
    expiry.addSeconds(expires);

    // Wipe old records
    var grDel = new GlideRecord('u_cisco_secure_access_csa_token');
    grDel.query();
    while (grDel.next()) {
      grDel.deleteRecord();
    }

    // Insert new record
    var gr = new GlideRecord('u_cisco_secure_access_csa_token');
    gr.initialize();
    gr.access_token = token;
    gr.expiry_date_time = expiry;
    gr.expires_in = expires;
    gr.token_type = parsed.token_type || "Bearer";
    gr.status = "Active";
	gr.created_on = new GlideDateTime();
    gr.insert();

    gs.info('Cisco token stored. Expires at ' + expiry);
    return token;
  },

  getToken: function() {
    var gr = new GlideRecord('u_cisco_secure_access_csa_token');
    if (gr.getFirstRow()) {
      var now = new GlideDateTime();
      if (now.after(gr.expiry_date_time)) {
        // Expired: update record before fetching new
        gr.status = "Expired";
        gr.update();

        gs.info('Token expired, fetching new one...');
        return this.fetchAndStoreToken();
      }
      return gr.access_token.toString();
    } else {
      gs.info('No token record found, fetching new one...');
      return this.fetchAndStoreToken();
    }
  },

  type: 'CiscoCSATokenManager'
};
